// Generated by AI
using UnityEngine;

[RequireComponent(typeof(Collider2D))]
public class MovingPlatform2D : MonoBehaviour
{
    [Header("Waypoints")]
    [SerializeField] private Transform pointA;
    [SerializeField] private Transform pointB;

    [Header("Movement Settings")]
    [SerializeField] private float moveSpeed = 2.5f;
    [SerializeField] private float waitAtEndpoints = 0.4f;
    [SerializeField] private bool startMovingToB = true;
    [SerializeField] private string playerObjectName = "Player";

    private Vector3 targetPosition;
    private Vector3 previousPosition;
    private float waitTimer;
    private Collider2D platformCollider;
    private Transform cachedPlayer;
    private Rigidbody2D cachedPlayerRb;

    private void Awake()
    {
        platformCollider = GetComponent<Collider2D>();
    }

    private void Start()
    {
        if (pointA == null || pointB == null)
        {
            Debug.LogWarning("MovingPlatform2D: Assign both PointA and PointB.", this);
            enabled = false;
            return;
        }

        transform.position = startMovingToB ? pointA.position : pointB.position;
        targetPosition = startMovingToB ? pointB.position : pointA.position;
        previousPosition = transform.position;
    }

    private void FixedUpdate()
    {
        if (pointA == null || pointB == null)
        {
            return;
        }

        previousPosition = transform.position;

        if (waitTimer > 0f)
        {
            waitTimer -= Time.fixedDeltaTime;
        }
        else
        {
            transform.position = Vector3.MoveTowards(
                transform.position,
                targetPosition,
                moveSpeed * Time.fixedDeltaTime
            );

            if (Vector3.Distance(transform.position, targetPosition) <= 0.01f)
            {
                transform.position = targetPosition;
                targetPosition = (targetPosition == pointB.position) ? pointA.position : pointB.position;
                waitTimer = waitAtEndpoints;
            }
        }

        Vector3 delta = transform.position - previousPosition;
        if (delta.sqrMagnitude <= Mathf.Epsilon)
        {
            return;
        }

        Transform player = GetPlayerTransform();
        if (player != null && IsPlayerStandingOnPlatform(player))
        {
            MovePlayerWithPlatform(player, delta);
        }
    }

    private void MovePlayerWithPlatform(Transform playerTransform, Vector3 delta)
    {
        if (cachedPlayerRb == null)
        {
            cachedPlayerRb = playerTransform.GetComponent<Rigidbody2D>();
        }

        if (cachedPlayerRb != null && cachedPlayerRb.bodyType == RigidbodyType2D.Dynamic)
        {
            cachedPlayerRb.MovePosition(cachedPlayerRb.position + (Vector2)delta);
        }
        else
        {
            playerTransform.position += delta;
        }
    }

    private Transform GetPlayerTransform()
    {
        if (cachedPlayer == null)
        {
            GameObject playerObj = GameObject.Find(playerObjectName);
            if (playerObj != null)
            {
                cachedPlayer = playerObj.transform;
                cachedPlayerRb = cachedPlayer.GetComponent<Rigidbody2D>();
            }
        }
        return cachedPlayer;
    }

    private bool IsPlayerStandingOnPlatform(Transform playerTransform)
    {
        if (platformCollider == null)
        {
            platformCollider = GetComponent<Collider2D>();
        }

        Collider2D playerCollider = playerTransform.GetComponentInChildren<Collider2D>();
        if (platformCollider == null || playerCollider == null)
        {
            return false;
        }

        float platformTop = platformCollider.bounds.max.y;
        float playerBottom = playerCollider.bounds.min.y;

        bool withinX = playerCollider.bounds.max.x >= platformCollider.bounds.min.x &&
                       playerCollider.bounds.min.x <= platformCollider.bounds.max.x;
        bool onTopSurface = playerBottom >= platformTop - 0.15f &&
                            Mathf.Abs(playerBottom - platformTop) <= 0.25f;

        return withinX && onTopSurface;
    }

    private void OnDrawGizmos()
    {
        if (pointA != null && pointB != null)
        {
            Gizmos.color = Color.cyan;
            Gizmos.DrawLine(pointA.position, pointB.position);
            Gizmos.DrawWireSphere(pointA.position, 0.2f);
            Gizmos.DrawWireSphere(pointB.position, 0.2f);
        }
    }
}